def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        # Start of a field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    i += 1
                    if i < n and line[i] == '"':
                        # Doubled quote, add one quote to field
                        field.append('"')
                        i += 1
                    else:
                        # End of quoted field
                        # Check that next char is comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        fields.append(''.join(field))
                        # Skip the comma if present
                        if i < n:
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            # Skip the comma if present
            if i < n:
                i += 1

    return fields

